      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 8/1~9) 30대 수도권 거주 남녀) 모바일 증권앱을 통한 주식투자자 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.07.24. 10:03\n조회 93\n구독\n고유링크) 8/1~9) 30대 수도권 거주 남녀) 모바일 증권앱을 통한 주식투자자 인터뷰\n모집이 마감되면 링크가 열리지 않으니 참고 부탁드립니다 ~\n조사구분 대면조사\n조사명 모바일 증권앱을 통한 주식투자자 인터뷰\n참여조건\n[영등포구 여의도동에서 진행하는 오프라인 인터뷰입니다.]\n조사대상: 현재 1개 이상의 모바일 MTS(주식증권 거래앱)을 활발히 사용하는 20세 이상 수도권 거주 남녀\n일정: 8월 1일 (일)~8월 9일(일) 중 (주말 참석 가능)\n(* 1) 조사 참여 전 현재 사용중인 모바일 증권앱 거래금액에 대한 인증사진 요청, 2) 인터뷰 시, 현재 귀하께서 사용중인 스마트폰 내 모바일 증권앱에 직접 접속해서 사용하는 과정을 녹화 예정)\n인증사진과 영상은 모두 인터뷰 내용 분석 및 보고서 등 조사 전반에만 활용되며, 조사 수행기관을 제외한 제3자에게 절대 제공되지 않습니다.\n조사장소 서울 영등포구 여의도동(추후 정확한 장소 안내)\n조사기간 2026-08-01 ~ 2026-08-09일 중 하루 / 시간은 추후 안내드립니다\n소요시간 2시간\n사례비 100,000원\n조사방법 1:1 인터뷰\n안내사항\n1) 조사 참여 전 현재 사용중인 모바일 증권앱 거래금액에 대한 인증사진 요청, 2) 인터뷰 시, 현재 귀하께서 사용중인 스마트폰 내 모바일 증권앱에 직접 접속해서 사용하는 과정을 녹화 예정입니다.\n인증사진과 영상은 모두 인터뷰 내용 분석 및 보고서 등 조사 전반에만 활용되며, 조사 수행기관을 제외한 제3자에게 절대 제공되지 않습니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/749?refuser=23341&intro=2\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 많이 본 동네소식 보러가기\n댓글\n2\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n초보입니다요오\n신입회원\nNew\n참석\n2026.07.24. 14:14 답글쓰기\n옵션\n좋아요\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.07.24. 21:28 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n고유링크) 8/1~9) 40대 수도권 거주 남녀) 모바일 증권앱을 통한 주식투자자 인터뷰\n좌담회알바좌담회카페\n26.07.24.\n댓글\n1\n고유링크) 8/1~9) 30대 수도권 거주 남녀) 모바일 증권앱을 통한 주식투자자 인터뷰\n좌담회알바좌담회카페\n26.07.24.\n댓글\n2\n고유링크) 8/1~9) 20대 수도권 거주 남녀) 모바일 증권앱을 통한 주식투자자 인터뷰\n좌담회알바좌담회카페\n26.07.24.\n댓글\n3\n8/6) 외국인 분들 대상 신용카드 좌담회\n좌담회알바좌담회카페\n26.07.24.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n2\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
