      "source_url": "https://albabank.pe.kr/%ec%9d%b8%ec%b2%b4%eb%b0%94%ec%9d%b4%ec%98%a4%eb%aa%a8%eb%8b%88%ed%84%b0%eb%a7%81/",
      "target_age": "",
      "target_gender": "",
      "target_condition": "",
      "date": "와 시간에 맞춰 진행되는 방식으로, 가까운 거점으로 한 번만 방문해 주시면 됩니다. 소요 시간은",
      "time": "",
      "duration": "은",
      "reward": "도 드립니다.",
      "location": "",
      "type": "기타",
      "raw_content": "# # 인체바이오모니터링\n식품의약품안전처의 지원을 받아 전국 8개의 대학교(충북대학교, 중앙대학교, 동아대학교, 동국대학교, 전남대학교, 제주대학교, 경희대학교, 삼육대학교)와 함께 영유아 및 임산부의 건강을 위한 환경유해인자 연구를 진행하고 있습니다.\n이 연구는 인체바이오모니터링을 통해 유해물질 노출을 평가하는 사업으로, [환경유해인자 노출이 스트레스, 우울 및 성장에 미치는 영향]을 위한 연구입니다. 연구에 참여하실\n만 6세 이하 영유아와 임산부\n분을 모집하고 있습니다.\n임신 중이시거나 만 6세 이하 자녀를 키우고 계신 분이라면 참여하실 수 있고요, 연구는 전국 주요 거점에서 특정 날짜와 시간에 맞춰 진행되는 방식으로, 가까운 거점으로 한 번만 방문해 주시면 됩니다. 소요 시간은\n약 1시간~ 1시간 30분\n정도로, 소정의 사례금도 드립니다.\n*답례품:\n농촌사랑 상품권\n1) 임산부 – 리워드 5만원 현장 지급 예정( 현장지급)\n2) 영유아 – 리워드 3만원 현장 지급 예정( 현장지급)\n사전에 온라인으로 사전조사 있습니다.\n현장 오시기전에 채뇨와 소변 가지고 오셔야 합니다 (오시기전에 ㅡ채뇨통과 소변통 택배로 보내드립니다)\n현장에서 설문지 및 채뇨통 제출, 동의서와 수검표 작성.\n임산부는 신체계측, 혈압, 채혈 진행, 영유아는 신체계측, 혈압 체크 후 현장에서 리워드 지급. (30분 소요)\n채혈 및 소변 채취 진행 (영유아는 소변만 진행), 현장에서 3종의 추가 설문조사 진행\n현장에서 작성하는 3종의 설문지가 양이 꽤 많습니다. 조사를 모두 마치는 데 1인 기준 최대 1시간 반 정도로 잡으셔야 합니다.\n글 탐색\n웰니스 관련 좌담회\n라면 맛테스트",
