      "raw_content": "# # 모바일 증권앱을 통한 주식투자자 인터뷰\n*대상조건:\n– 20세 이상 수도권 거주 남녀\n– 현재 1개 이상의 모바일 MTS(주식증권 거래앱)을 활발히 사용하는 분\n*일정: 8월 1일(일) ~ 8월 9일(일) 중 (주말 참석 가능)\n*소요시간: 2시간\n*사례비: 100,000원\n*장소: 서울 영등포구 여의도동(추후 정확한 장소 안내)\n*안내사항:\n1) 조사 참여 전 현재 사용중인 모바일 증권앱 거래금액에 대한 인증사진 요청\n2) 인터뷰 시, 현재 귀하께서 사용중인 스마트폰 내 모바일 증권앱에 직접 접속해서 사용하는 과정을 녹화 예정입니다.\n인증사진과 영상은 모두 인터뷰 내용 분석 및 보고서 등 조사 전반에만 활용되며, 조사 수행기관을 제외한 제3자에게 절대 제공되지 않습니다.\n<신청 방법>\n▷ 아래 URL에 접속하여 설문응답 진행해주세요. 신청해 주신 내용을 바탕으로 대상자가 되시면 저희가 순차적으로 전화 드립니다. 통화 후 참여 명단에 등록해드리며, 명단에 등록되셔야 참여 가능하니 참고 부탁드립니다.\nhttps://www.hrc-ms.com/participate/improSurvey/749?refuser=22336&intro=2\n글 탐색\n라면 맛테스트\n실제 재난피해자(폭염/산불/풍수해) 좌담회",
