      "type": "좌담회",
      "raw_content": "# # 실제 재난피해자(폭염/산불/풍수해) 좌담회\n*대상조건:\n[그룹 구성에 따라 진행방식(온라인/오프라인)과 사전 질문이 다르오니 참고하셔서 신청 부탁드립니다.]\n(산불-온라인 좌담회)\n2025년도 재난피해 회복수준 실태조사 대상 재난으로 인해 신체적 ·정신적 또는 재산 피해를 입은 그룹\n주요 피해지역: 25년 3월 전국 동시다발 산불(경기 의성군,안동시,청송군,영양군,영덕군 등) / 23년 4월 산불(강원 강릉시, 충남 금산군,전남 순천시, 대전 서구 등) / 22년 경북,강원 동해안 산불(경북 울진군,강원 삼척시, 강원 동해시, 강릉시, 경북 울릉군)\n피해특징: 산림,주택,문화재 피해 및 대규모 주민 대피 / 주택 및 산림 피해 / 대규모 산림 소실 등\n(풍수해-온라인 좌담회)\n2025년도 재난피해 회복수준 실태조사 대상 재난으로 인해 신체적 ·정신적 또는 재산 피해를 입은 그룹\n주요 피해지역: 24년 11.26~28 대설,강풍,풍랑 / 24년 호우 피해 / 23년 태풍 카눈 / 22년 태풍 힌남노 등\n피해특징: 기록적 습설로 축사,시설하우스 붕괴 등 농업시설 피해 / 주택,농경지 침수 및 하천 범람 / 예천 산사태 등 인명 시설 피해 / 포항 도심 침수 / 수도권 반지하 침수 등\n(폭염-수도권:대면 좌담회 / 비수도권:온라인 좌담회)\n25년도 폭염으로 인해 신체적 ·정신적 증상을 경험한 자\n대도시 열섬형(서울,대구) 농촌 고령형(전남, 경북 농촌) 옥외 노동자 강원 산간지역\n*일정: 2026-08-06 ~ 2026-08-18\n*소요시간: 2시간\n*사례비: 80,000원\n*장소: 강남구 논현동 한국리서치 본사 (9호선:언주역)\n*안내사항:\n비수도권(풍수해/산불/폭염 각 1그룹씩): 비대면 온라인 좌담회\n수도권(폭염 피해자 1그룹): 본사 방문 좌담회\n<신청 방법>\n▷ 아래 URL에 접속하여 설문응답 진행해주세요. 신청해 주신 내용을 바탕으로 대상자가 되시면 저희가 순차적으로 전화 드립니다. 통화 후 참여 명단에 등록해드리며, 명단에 등록되셔야 참여 가능하니 참고 부탁드립니다.\nhttps://www.hrc-ms.com/participate/improSurvey/748?refuser=22336&intro=2\n글 탐색\n모바일 증권앱을 통한 주식투자자 인터뷰\n국민 정신 건강 관련 좌담회",
