      "raw_content": "# # 건강한 노화 및 장수 관련 가정방문 인터뷰\n*대상조건:\n– 45~65세 서울 거주 남여\n– 건강과 노화에 관심이 많아서 정보를 찾아보고 실천하는 사람\n*조사방법:\n댁으로 3~4명 정도 방문하여 최대 2시간 30분 가량 인터뷰 녹음 내용 및 자택 내부 공개, 사진 또는 동영상 촬영을 하면서 진행이 됩니다.\n촬영한 동영상, 사진, 녹음된 내용은 조사 목적으로만 쓰이고 외부로는 유출되지 않습니다\n인터뷰 전 사전과제가 있음(사전 셀프 동영상 포함 하루에 5분~10분 소요 3일~5일간)\n모두 참여가 가능하셔야 합니다.\n*일정: 8월 18일(화)~21일(금) – 구체적인 일정은 협의\n*소요시간: 인터뷰 2시간 30분/ 사전과제(3~5일간, 하루 5~10분)\n*사례비: 25~30만원(사전과제비 포함)\n글 탐색\n웹/모바일 검색 행태 관련 웹다이어리(만20-29세 남여)",
